import * as THREE from 'three';
const GAP = 24; // px between the page's foot and the pill (clear of the book's edge below the page)
export default class PageLinks {
    constructor() {
        this.v = new THREE.Vector3();
        const make = () => {
            const a = document.createElement('a');
            a.className = 'page-link';
            a.target = '_blank';
            a.rel = 'noopener';
            a.tabIndex = -1;
            // the arrow drawn, not the ↗ character: iOS shows that as a colour emoji
            a.innerHTML = '<span class="page-link-label"></span><svg class="page-link-arrow" viewBox="0 0 10 10" aria-hidden="true">'
                + '<path d="M2.5 7.5 L7.5 2.5 M3.5 2.5 H7.5 V6.5" /></svg>';
            document.body.appendChild(a);
            return a;
        };
        this.pills = [make(), make()];
    }
    /**
     * @param root    the book's frame (BookPages: the fold along z at x = 0, pages in y = 0, the right page x > 0)
     * @param at      where the pages' feet are in it: half a page's width out from the fold, and the foot's z
     * @param links   the open spread's left and right page links (null: none, or hidden)
     */
    update(root, camera, at, links) {
        this.pills.forEach((a, i) => {
            const link = links[i];
            a.classList.toggle('is-shown', !!link);
            a.tabIndex = link ? 0 : -1;
            if (!link)
                return;
            if (a.dataset.url !== link.url) {
                a.dataset.url = a.href = link.url;
                a.querySelector('.page-link-label').textContent = link.label.toUpperCase();
                a.setAttribute('aria-label', `Open ${link.title} on ${link.label}`);
            }
            this.v.set(i === 0 ? -at.x : at.x, 0, at.z).applyMatrix4(root.matrixWorld).project(camera);
            const x = ((this.v.x + 1) / 2) * window.innerWidth, y = ((1 - this.v.y) / 2) * window.innerHeight;
            a.style.transform = `translate(${x.toFixed(1)}px, ${(y + GAP).toFixed(1)}px) translateX(-50%)`;
        });
    }
    hide() { for (const a of this.pills) {
        a.classList.remove('is-shown');
        a.tabIndex = -1;
    } }
}
