import * as THREE from 'three';
import Time from '../Utils/Time';
import { IDLE_FOCUS, IDLE_ORIGIN, idleCameraPosition, idleClock } from './IdlePath';
export class CameraKeyframeInstance {
    constructor(keyframe) {
        this.position = keyframe.position;
        this.focalPoint = keyframe.focalPoint;
    }
    update() { }
}
const keys = {
    idle: {
        position: IDLE_ORIGIN.clone(),
        focalPoint: IDLE_FOCUS.clone(),
    },
    // the desk and screen views are framed for the window's shape by Interaction.ts, which sets these every frame
    monitor: {
        position: new THREE.Vector3(-357, 914, 4000),
        focalPoint: new THREE.Vector3(-357, 914, -117),
    },
    desk: {
        position: new THREE.Vector3(-357, 3500, 9000),
        focalPoint: new THREE.Vector3(-357, 500, 0),
    },
    // the loading screen already runs the idle sweep (see IdlePath.ts), so the camera never jumps when it fades
    loading: {
        position: IDLE_ORIGIN.clone(),
        focalPoint: IDLE_FOCUS.clone(),
    },
};
export class LoadingKeyframe extends CameraKeyframeInstance {
    constructor() {
        const keyframe = keys.loading;
        super(keyframe);
    }
    // follows the idle sweep at the loading screen's clock, so the room lines up with its drawing
    update() {
        idleCameraPosition(idleClock.ms, this.position);
    }
}
export class IdleKeyframe extends CameraKeyframeInstance {
    constructor() {
        const keyframe = keys.idle;
        super(keyframe);
        this.held = false;
        this.heldAt = 0;
        this.pausedMs = 0; // time spent held: the sweep picks up where it stopped
        this.origin = new THREE.Vector3().copy(keyframe.position);
        this.time = new Time();
    }
    /** Stops the sweep where it is (the notebook is out), or lets it carry on from there. */
    hold(on) {
        if (on === this.held)
            return;
        if (on)
            this.heldAt = this.time.elapsed;
        else
            this.pausedMs += this.time.elapsed - this.heldAt;
        this.held = on;
    }
    // the sweep continues from where the loading screen left it (time.elapsed restarts when loading is done)
    update() {
        if (this.held)
            return;
        idleCameraPosition(this.time.elapsed - this.pausedMs + idleClock.ms, this.position);
    }
}
/** A keyframe that holds still where it is put (the desk and screen views, posed by Interaction.ts). */
export function keyframe(key) {
    const k = keys[key];
    return new CameraKeyframeInstance({ position: k.position.clone(), focalPoint: k.focalPoint.clone() });
}
