import Application from '../Application';
import BakedModel from '../Utils/BakedModel';
export default class Environment {
    constructor() {
        this.application = new Application();
        this.scene = this.application.scene;
        this.resources = this.application.resources;
        this.bakeModel();
        this.setModel();
    }
    bakeModel() {
        const { gltfModel, texture } = this.resources.items;
        // Room, rock face and the sea/sky backdrop each carry their own baked texture
        this.bakedModels = [
            new BakedModel(gltfModel.environmentModel, texture.environmentTexture, 900, 'environment'),
            new BakedModel(gltfModel.rockModel, texture.rockTexture, 900, 'rock'),
            new BakedModel(gltfModel.exteriorModel, texture.exteriorTexture, 900, 'exterior'),
            // Chair, bench and desk props share one baked texture
            new BakedModel(gltfModel.propsModel, texture.propsTexture, 900, 'props'),
        ];
    }
    setModel() {
        for (const bakedModel of this.bakedModels) {
            this.scene.add(bakedModel.getModel());
        }
    }
    update() { }
}
