// A pile of things lying on each other (the books on the right of the desk: Books.ts), bottom to top. It only knows
// heights: each item rests on the top of the one below it, the lowest on the base. Taking an item out lifts what's on
// it a little first, so the item slides out from under without passing through them, then lets them drop onto what is
// left below; putting one back lays it on top. Anything that can say how thick it is and take a resting height can be
// piled (Stackable): more books, or other things, follow the same rules.
const RISE = 0.45; // what's above an item taken out rises by this part of the item's thickness...
const RISE_MIN = 12; // ... at least this much (site units)
export default class Pile {
    /** @param items bottom to top  @param base the height the lowest rests on */
    constructor(items, base) {
        this.items = items;
        this.base = base;
        this.restack();
    }
    has(item) { return this.items.includes(item); }
    get top() { return this.items[this.items.length - 1]; }
    /** The height of the pile's top: where an item put on it rests. */
    get height() { return this.items.reduce((y, it) => y + it.thickness, this.base); }
    /**
     * Takes an item out from wherever it is: what was on it rises to let it out, then drops onto what's left.
     * @returns whether something was on it (so it should slide out sideways before lifting)
     */
    take(item) {
        const i = this.items.indexOf(item);
        if (i < 0)
            return false;
        this.items.splice(i, 1);
        const rise = Math.max(RISE_MIN, item.thickness * RISE);
        this.restack(i, { delay: 0, rise, hold: item.clearMs });
        return i < this.items.length;
    }
    /** Puts an item on top (it gets there by itself: its resting height is set, it moves there when it comes back). */
    put(item) {
        if (this.has(item))
            return;
        item.setRest(this.height, this.items.length > 0);
        this.items.push(item);
    }
    /** Rests each item from `from` up on the one below it (or the base). */
    restack(from = 0, motion) {
        let y = this.base;
        this.items.forEach((it, i) => { if (i >= from)
            it.setRest(y, i > 0, motion); y += it.thickness; });
    }
}
