import * as THREE from 'three';
import { palette, onThemeChange, srgb } from '../Theme';
// Wash for the room while the loader hands over: the room grows outward from the desk, and its edge bleeds from
// paper into colour like ink in water. Fragments not reached yet are discarded, and the paper half of the edge is
// left see-through rather than painted in the paper's colour: the loader's paper behind the canvas shows there
// instead, and looks the same, but the room's last pass (grain and vignette, Renderer.setFinish) only touches what
// the canvas covers, so the paper stays clean. Depth still writes as for any solid surface, so nothing sorts wrongly.
export const dissolveUniforms = {
    uReveal: { value: 1 },
    uOrigin: { value: new THREE.Vector3() },
    uRadius: { value: 40000 },
    uPaper: { value: new THREE.Vector3() },
    uInk: { value: new THREE.Vector3() }, // the tint at the wash's edge (the palette's wash colour)
};
const setColours = () => { const p = palette(); srgb(p.paper, dissolveUniforms.uPaper.value); srgb(p.wash, dissolveUniforms.uInk.value); };
setColours();
onThemeChange(setColours);
const NOISE = /* glsl */ `
varying vec3 vDissolveWorld;
uniform float uReveal;
uniform vec3 uOrigin;
uniform float uRadius;
uniform vec3 uPaper;
uniform vec3 uInk;
float dh(vec3 p) { p = fract(p * 0.3183099 + 0.1); p *= 17.0; return fract(p.x * p.y * p.z * (p.x + p.y + p.z)); }
float dnoise(vec3 x) {
    vec3 i = floor(x), f = fract(x); f = f * f * (3.0 - 2.0 * f);
    return mix(mix(mix(dh(i), dh(i + vec3(1, 0, 0)), f.x), mix(dh(i + vec3(0, 1, 0)), dh(i + vec3(1, 1, 0)), f.x), f.y),
               mix(mix(dh(i + vec3(0, 0, 1)), dh(i + vec3(1, 0, 1)), f.x), mix(dh(i + vec3(0, 1, 1)), dh(i + vec3(1, 1, 1)), f.x), f.y), f.z);
}
float dfbm(vec3 p) { return 0.55 * dnoise(p) + 0.3 * dnoise(p * 2.03) + 0.15 * dnoise(p * 4.1); }
`;
const FRAGMENT = /* glsl */ `
#include <encodings_fragment>
if (uReveal < 1.0) {
    float n = dfbm(vDissolveWorld / 1800.0);
    float fine = dfbm(vDissolveWorld / 450.0);                 // small grain for the edge
    // distance from the desk, roughened by the noise, against a front that moves outward (sea and sky last)
    float d = min(distance(vDissolveWorld, uOrigin) / uRadius, 1.0) + (n - 0.5) * 0.12 + (fine - 0.5) * 0.06;
    float front = uReveal * 1.2 - 0.08;
    float k = smoothstep(front - 0.14, front, d);              // 0 = full colour, 1 = paper
    if (k >= 0.999) discard;
    float bleed = smoothstep(front - 0.14, front - 0.04, d) * (1.0 - smoothstep(front - 0.04, front, d));
#ifdef DISSOLVE_BLENDED
    // see-through materials are blended by the GPU: fade their own alpha, the paper shows behind
    gl_FragColor.a *= 1.0 - k;
#else
    // solid ones are written as they are, premultiplied (the canvas's format): the colour covering 1 - k of the
    // pixel, the ink bleed over it, the paper behind for the rest; the same mix as before, over the real paper
    float o = bleed * 0.35;
    float cover = gl_FragColor.a * (1.0 - k);
    gl_FragColor = vec4(uInk * o + gl_FragColor.rgb * cover * (1.0 - o), o + cover * (1.0 - o));
#endif
}
`;
/**
 * Adds a shader hook on top of the material's existing one (the time-of-day crossfade, TimeOfDay.ts), with a program
 * cache key that tells the combinations apart.
 */
function extendShader(material, key, hook) {
    const before = material.onBeforeCompile.bind(material);
    const beforeKey = material.customProgramCacheKey();
    material.onBeforeCompile = (shader, renderer) => { before(shader, renderer); hook(shader); };
    material.customProgramCacheKey = () => beforeKey + '|' + key;
    material.needsUpdate = true;
}
/** Adds the dissolve to a material (shared uniforms, so one value drives every material). */
export function addDissolve(material) {
    const blended = material.transparent;
    extendShader(material, blended ? 'dissolve-blended' : 'dissolve', (shader) => {
        Object.assign(shader.uniforms, dissolveUniforms);
        shader.vertexShader = 'varying vec3 vDissolveWorld;\n' + shader.vertexShader.replace('#include <project_vertex>', '#include <project_vertex>\nvDissolveWorld = (modelMatrix * vec4(transformed, 1.0)).xyz;');
        shader.fragmentShader = (blended ? '#define DISSOLVE_BLENDED\n' : '') + NOISE + shader.fragmentShader.replace('#include <encodings_fragment>', FRAGMENT);
    });
}
/**
 * A plain fade from paper for things that should just appear (the sea and sky): the material stays opaque, so where
 * two surfaces overlap only the nearest one shows, and it goes from see-through (the paper behind the canvas) to its
 * own colour, written premultiplied as in the dissolve.
 */
export function addPaperFade(material) {
    const uniform = { value: 1 };
    extendShader(material, 'paper-fade', (shader) => {
        shader.uniforms.uPaperFade = uniform;
        shader.fragmentShader = 'uniform float uPaperFade;\n' + shader.fragmentShader.replace('#include <encodings_fragment>', '#include <encodings_fragment>\ngl_FragColor *= uPaperFade;');
    });
    return uniform;
}
