import UIEventBus from '../UI/EventBus';
import EventEmitter from './EventEmitter';
import { fpsCap } from './Perf';
export default class Time extends EventEmitter {
    constructor() {
        super();
        // Setup
        this.start = Date.now();
        this.current = this.start;
        this.elapsed = 0;
        this.delta = 16;
        window.requestAnimationFrame(() => {
            this.tick();
        });
        UIEventBus.on('loadingScreenDone', () => {
            // reset now, not at the next tick: the idle camera reads elapsed in the same frame and would jump ahead
            this.start = Date.now();
            this.current = this.start;
            this.elapsed = 0;
        });
    }
    tick() {
        // ?fps=<n>: frames come no faster than that (one is skipped until its time has come)
        const cap = fpsCap();
        if (cap && Date.now() - this.current < 1000 / cap - 2) {
            window.requestAnimationFrame(() => this.tick());
            return;
        }
        const currentTime = Date.now();
        this.delta = currentTime - this.current;
        this.current = currentTime;
        this.elapsed = this.current - this.start;
        this.trigger('tick');
        window.requestAnimationFrame(() => {
            this.tick();
        });
    }
}
