import * as THREE from 'three';
// A book's pages (World/Book.ts holds the book itself). Only four page surfaces ever exist, however many
// pages the book has: the two fixed pages of the open spread (L, R) and the two sides of one turning sheet (F, B).
//
// Turning forward, spread n -> n+1: the sheet appears flat over R showing what R shows (right of n), its back carrying
// the next left page; R is switched, hidden under it, to the next right page; the sheet turns over onto the left and
// lands showing that left page; L is switched to the same page under it and the sheet fades out. Backwards is the
// mirror. Every switch happens under an identical surface, so the eye only sees a page turn.
// Hovering the outer edge of a page lifts the sheet's corner a little there, the turn it hints at already set up
// (so what peeks out from under the corner is the page that will show).
//
// The sheet is a grid bent in its vertex shader: it turns about the fold (uAngle, 0 = lying on the right, PI = on
// the left) while its outer part trails behind (uBeta: a steady bend from the fold out, strongest mid-turn, zero at
// both ends so it lands flat); the hint adds a little bend of its own near the pointer.
//
// What each page shows comes from a PageSource (Diary.ts): blank paper for most books, the diary for the notebook.
const TURN_MS = 650;
const QUICK_MS = 420; // a turn asked for while one is running, so flicking through keeps up
const FADE_MS = 150; // the sheet fading into the fixed page under it, once it has landed
const TRAIL = 0.95; // how far the outer edge trails at mid-turn (radians)
const HINT = 0.13; // the hint's lift at the edge (radians)
const HINT_MS = 220;
const EDGE = 0.24; // the outer part of a page that turns it (and hints), as a part of its width
const LIFT = 0.8; // the sheet floats this far over the fixed pages (site units)
const PX_W = 768; // a page canvas's width (its height follows the page's proportions)
const ease = (t) => (t < 0.5 ? 4 * Math.pow(t, 3) : 1 - Math.pow((-2 * t + 2), 3) / 2);
const clamp01 = (t) => Math.min(1, Math.max(0, t));
const vertex = /* glsl */ `
uniform float uAngle, uBeta, uHint, uHintZ, uHintSign, uLift, uZ0, uZ1;
varying vec2 vUv;
varying float vShade, vUp;
void main() {
    float s = position.x;                                   // distance from the fold, along the sheet
    float zn = (position.z - uZ0) / (uZ1 - uZ0);
    float b = uBeta + uHintSign * uHint * exp(-pow((zn - uHintZ) / 0.3, 2.0));
    float a = uAngle - b * s;                               // the sheet's direction at s (it bends steadily)
    vec2 p = abs(b) < 1e-7 ? s * vec2(cos(uAngle), sin(uAngle))
                           : vec2(sin(uAngle) - sin(a), cos(a) - cos(uAngle)) / b;
    vec2 n = vec2(-sin(a), cos(a));
    vShade = dot(n, normalize(vec2(-0.3, 1.0)));
    vUp = n.y;                                              // > 0: this part still leans right, its front faces the reader
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(p.x, p.y + uLift, position.z, 1.0);
}`;
const fragment = /* glsl */ `
uniform sampler2D tFront, tBack;
uniform float uFade;
varying vec2 vUv;
varying float vShade, vUp;
void main() {
    // which page shows is decided by the paper's own lean, not by which way the triangles face: the front while it
    // leans right, the back once it is past upright (it changes where the paper is edge-on and shows nothing). The
    // back is mirrored across, so it reads upright lying on the left
    bool front = vUp > 0.0;
    vec4 c = front ? texture2D(tFront, vUv) : texture2D(tBack, vec2(1.0 - vUv.x, vUv.y));
    float k = 0.84 + 0.16 * clamp(front ? vShade : -vShade, -1.0, 1.0);
    gl_FragColor = linearToOutputTexel(vec4(c.rgb * k, uFade));
}`;
// the turning sheet's shadow on the fixed pages: darkest along the line under its outer edge
const shadowVertex = /* glsl */ `
varying float vX;
void main() { vX = position.x; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }`;
const shadowFragment = /* glsl */ `
uniform float uEdge, uStrength, uSoft;
varying float vX;
void main() { gl_FragColor = vec4(0.0, 0.0, 0.0, uStrength * exp(-abs(vX - uEdge) / uSoft)); }`;
export default class NotebookPages {
    /**
     * @param root     the book's frame: the fold along z at x = 0, the open pages lying in y = 0, right page x > 0
     * @param page     the right page's extent in that frame (the left one is its mirror)
     * @param paper    the fixed pages' materials, given their textures here
     * @param source   what the pages show
     * @param start    the spread it opens at (the notebook opens where its ribbon is: the last)
     */
    constructor(root, page, paper, source, start = 'first') {
        this.spread = 0; // the open spread: pages 2n+1 (left) and 2n+2 (right)
        this.armed = 0; // the sheet is set up for a turn this way (hovered or turning)
        this.turn = null;
        this.fade = null; // when the landed sheet began fading out
        this.queued = 0;
        this.hint = { on: 0, target: 0, z: 0.5, last: performance.now() };
        this.source = source;
        this.spreads = Math.max(1, Math.ceil(source.pages / 2));
        if (start === 'last')
            this.spread = this.spreads - 1;
        this.pw = page.max.x;
        this.z0 = page.min.z;
        this.z1 = page.max.z;
        this.px = { w: PX_W, h: Math.round((PX_W * (this.z1 - this.z0)) / this.pw) };
        const tex = (enc) => { const t = new THREE.Texture(); t.encoding = enc; t.anisotropy = 4; return t; };
        this.fixed = { L: tex(THREE.sRGBEncoding), R: tex(THREE.sRGBEncoding) };
        paper.left.map = this.fixed.L;
        paper.right.map = this.fixed.R;
        paper.left.needsUpdate = paper.right.needsUpdate = true;
        // the sheet: a grid from the fold out (x = distance from it), the page's top to foot along z
        const C = 36, Rw = 14, P = [], U = [], I = [];
        for (let j = 0; j <= Rw; j++)
            for (let i = 0; i <= C; i++) {
                const z = this.z0 + ((this.z1 - this.z0) * j) / Rw;
                P.push((this.pw * i) / C, 0, z);
                U.push(i / C, (this.z1 - z) / (this.z1 - this.z0));
            }
        for (let j = 0; j < Rw; j++)
            for (let i = 0; i < C; i++) {
                const a = j * (C + 1) + i, b = a + C + 1, c = a + 1, d = b + 1;
                I.push(a, c, b, c, d, b);
            }
        const g = new THREE.BufferGeometry();
        g.setAttribute('position', new THREE.Float32BufferAttribute(P, 3));
        g.setAttribute('uv', new THREE.Float32BufferAttribute(U, 2));
        g.setIndex(I);
        // the sheet's canvases are read and written as the fixed pages' MeshBasicMaterial does (sRGB textures, the
        // renderer's output encoding), so its smaller mip levels match theirs: averaged raw, thin ink lines came out
        // heavier on the sheet than on the page under it
        this.uniforms = {
            tFront: { value: tex(THREE.sRGBEncoding) }, tBack: { value: tex(THREE.sRGBEncoding) },
            uAngle: { value: 0 }, uBeta: { value: 0 }, uHint: { value: 0 }, uHintZ: { value: 0.5 }, uHintSign: { value: -1 },
            uLift: { value: LIFT }, uZ0: { value: this.z0 }, uZ1: { value: this.z1 }, uFade: { value: 1 },
        };
        const m = new THREE.ShaderMaterial({ uniforms: this.uniforms, vertexShader: vertex, fragmentShader: fragment, side: THREE.DoubleSide, transparent: true });
        this.sheet = new THREE.Mesh(g, m);
        this.sheet.visible = false;
        this.sheet.frustumCulled = false;
        root.add(this.sheet);
        this.shadowU = { uEdge: { value: 0 }, uStrength: { value: 0 }, uSoft: { value: this.pw * 0.22 } };
        const sg = new THREE.PlaneGeometry(2 * this.pw, this.z1 - this.z0).rotateX(-Math.PI / 2).translate(0, LIFT * 0.4, (this.z0 + this.z1) / 2);
        const sm = new THREE.ShaderMaterial({ uniforms: this.shadowU, vertexShader: shadowVertex, fragmentShader: shadowFragment, transparent: true, depthWrite: false });
        this.shadow = new THREE.Mesh(sg, sm);
        this.shadow.visible = false;
        root.add(this.shadow);
        this.show(this.fixed.L, this.left(this.spread));
        this.show(this.fixed.R, this.right(this.spread));
    }
    left(n) { return 2 * n + 1; }
    right(n) { return 2 * n + 2; }
    /** Puts a page on a surface (pages are drawn once and kept). */
    show(t, page) {
        const c = this.source.draw(page, this.px.w, this.px.h);
        if (t.image !== c) {
            t.image = c;
            t.needsUpdate = true;
        }
    }
    /** The last spread (where the notebook's ribbon lies). */
    get last() { return this.spreads - 1; }
    canTurn(dir) { return dir > 0 ? this.spread < this.spreads - 1 : this.spread > 0; }
    /** Takes its sheet and shadow out of the book (it is being replaced). */
    dispose() {
        for (const m of [this.sheet, this.shadow]) {
            m.removeFromParent();
            m.geometry.dispose();
            m.material.dispose();
        }
    }
    /** Which turn a point on the open book asks for: its outer edges (in the book's frame). */
    zoneAt(x, z) {
        if (z < this.z0 || z > this.z1 || Math.abs(x) > this.pw || Math.abs(x) < this.pw * (1 - EDGE))
            return null;
        const dir = x > 0 ? 1 : -1;
        return { dir, z: (z - this.z0) / (this.z1 - this.z0), end: !this.canTurn(dir) };
    }
    /**
     * Sets the sheet up to turn this way, lying where it starts and showing what the page under it shows, and puts
     * what will be uncovered on the page underneath.
     */
    arm(dir) {
        if (this.armed === dir)
            return;
        this.disarm();
        const n = this.spread, u = this.uniforms;
        if (dir > 0) { // over R: front = this right page, back = the next left page; under it, the next right page
            this.show(u.tFront.value, this.right(n));
            this.show(u.tBack.value, this.left(n + 1));
            this.show(this.fixed.R, this.right(n + 1));
            u.uAngle.value = 0;
            u.uHintSign.value = -1;
        }
        else { // over L: back = this left page, front = the previous right page; under it, the previous left page
            this.show(u.tBack.value, this.left(n));
            this.show(u.tFront.value, this.right(n - 1));
            this.show(this.fixed.L, this.left(n - 1));
            u.uAngle.value = Math.PI;
            u.uHintSign.value = 1;
        }
        u.uBeta.value = 0;
        u.uFade.value = 1;
        this.sheet.visible = true;
        this.armed = dir;
    }
    /** Back to just the spread (the sheet lying flat over the page it matches, so taking it away shows nothing). */
    disarm() {
        if (!this.armed)
            return;
        this.show(this.fixed.L, this.left(this.spread));
        this.show(this.fixed.R, this.right(this.spread));
        this.sheet.visible = false;
        this.shadow.visible = false;
        this.armed = 0;
    }
    /** The pointer over the book (null: off the edges). Lifts the corner there while nothing is turning. */
    hover(zone) {
        if (this.turn || this.fade !== null)
            return;
        if (zone && !zone.end) {
            this.arm(zone.dir);
            this.hint.target = 1;
            this.hint.z = zone.z;
        }
        else
            this.hint.target = 0;
    }
    go(dir) {
        if (this.turn || this.fade !== null) {
            if (this.canTurn(dir) || this.turn)
                this.queued = dir;
            return;
        }
        if (!this.canTurn(dir))
            return;
        this.arm(dir);
        this.turn = { dir, t0: performance.now(), ms: this.queued ? QUICK_MS : TURN_MS };
        this.queued = 0;
    }
    /** Puts the spread back to plain pages at once (the book is closing). */
    reset() { this.turn = null; this.fade = null; this.queued = 0; this.hint.on = this.hint.target = 0; this.uniforms.uHint.value = 0; this.disarm(); }
    update() {
        const now = performance.now(), u = this.uniforms;
        // the hint eases in and out; a turn takes it away as it starts
        const dt = now - this.hint.last;
        this.hint.last = now;
        const target = this.turn ? 0 : this.hint.target;
        this.hint.on += Math.sign(target - this.hint.on) * Math.min(Math.abs(target - this.hint.on), dt / HINT_MS);
        u.uHint.value = (ease(this.hint.on) * HINT) / this.pw;
        u.uHintZ.value += (this.hint.z - u.uHintZ.value) * 0.2;
        if (this.turn) {
            const { dir, t0, ms } = this.turn, t = clamp01((now - t0) / ms), e = ease(t);
            const angle = dir > 0 ? e * Math.PI : (1 - e) * Math.PI;
            u.uAngle.value = angle;
            u.uBeta.value = (dir * TRAIL * Math.sin(angle)) / this.pw;
            // the shadow under the outer edge, deepest when the sheet stands highest
            const b = u.uBeta.value, s = this.pw, a = angle - b * s;
            this.shadowU.uEdge.value = Math.abs(b) < 1e-7 ? s * Math.cos(angle) : (Math.sin(angle) - Math.sin(a)) / b;
            this.shadowU.uStrength.value = 0.32 * Math.sin(angle);
            this.shadow.visible = true;
            if (t >= 1) {
                // landed: the page under it takes what it shows, then the sheet goes
                this.turn = null;
                this.shadow.visible = false;
                u.uBeta.value = 0;
                this.spread += dir;
                if (dir > 0)
                    this.show(this.fixed.L, this.left(this.spread));
                else
                    this.show(this.fixed.R, this.right(this.spread));
                if (this.queued && this.canTurn(this.queued)) {
                    this.armed = 0;
                    this.sheet.visible = false;
                    const q = this.queued;
                    this.go(q);
                }
                else {
                    this.queued = 0;
                    this.fade = now;
                }
            }
        }
        else if (this.fade !== null) {
            const f = clamp01((now - this.fade) / FADE_MS);
            u.uFade.value = 1 - f;
            if (f >= 1) {
                this.fade = null;
                this.armed = 0;
                this.sheet.visible = false;
                u.uFade.value = 1;
                if (this.queued) {
                    const q = this.queued;
                    this.queued = 0;
                    this.go(q);
                }
            }
        }
        else if (this.armed && this.hint.on <= 0 && this.hint.target === 0) {
            this.disarm(); // the hint has settled flat: nothing to show
        }
    }
}
